const b=($input.first().json.body||{});
const text=b.text;
if(!text||!String(text).trim()){return [{json:{success:false,error:'Ders notu bos olamaz.',skip:true}}];}
let count=parseInt(b.count,10); if(!(count>=3&&count<=25)) count=10;
const sys='Sen bir universite egitim asistanisin. Verilen ders notundan Turkce bilgi kartlari (flashcard) uret. '+
'Sadece metindeki bilgileri kullan, disaridan bilgi ekleme. Her kartin on yuzu kisa ve net bir soru veya kavram, '+
'arka yuzu 1-2 cumlelik dogru cevap olsun. Kartlar birbirini tekrar etmesin. '+
'Yalnizca su JSON bicimiyle yanit ver: {"cards":[{"front":"...","back":"..."}]}';
return [{json:{count, ollamaBody:{model:'qwen2.5:7b',stream:false,format:'json',options:{temperature:0.3},messages:[
{role:'system',content:sys},
{role:'user',content:'Tam olarak '+count+' kart uret. Ders notu:\n\n'+String(text)}]}}}];

const j=$input.first().json;
const raw=j.message&&j.message.content;
if(!raw){return [{json:{success:false,error:'Yapay zeka yanit veremedi.'}}];}
let data;
try{data=JSON.parse(raw);}catch(e){
  const m=String(raw).match(/\{[\s\S]*\}/);
  try{data=m?JSON.parse(m[0]):null;}catch(e2){data=null;}
}
let list=Array.isArray(data)?data:(data&&(data.cards||data.flashcards||data.kartlar));
if(!Array.isArray(list)){return [{json:{success:false,error:'Kartlar okunamadi. Tekrar deneyin.'}}];}
const seen=new Set();
const cards=[];
for(const c of list){
  if(!c||typeof c!=='object') continue;
  const f=String(c.front||c.soru||c.question||'').trim();
  const bk=String(c.back||c.cevap||c.answer||'').trim();
  if(!f||!bk||seen.has(f.toLowerCase())) continue;
  seen.add(f.toLowerCase());
  cards.push({front:f,back:bk});
}
if(cards.length<3){return [{json:{success:false,error:'Yeterli kart uretilemedi. Daha uzun bir not ile deneyin.'}}];}
return [{json:{success:true,cards}}];
